arguments.command:
cat > /app/experiments/matrix.py <<'PY'
from pathlib import Path
import subprocess, re, json
base=Path('/app/experiments');out=[]
for c in ['tt','ff','ss','fs','sf']:
 for v in [1.8,1.98]:
  for t in [-25,27,85]:
   row=dict(corner=c,vdd=v,temp=t)
   for kind in ['loop_nominal','nominal','noise_nominal']:
    s=(base/f'tb_{kind}.spi').read_text().replace('" tt','" '+c).replace('VDD vdd vss 1.8',f'VDD vdd vss {v}').replace('.include',f'.temp {t}\n.include')
    name=f'{c}_{v}_{t}_{kind}';p=base/(name+'.spi');p.write_text(s)
    subprocess.run(['ngspice','-b',str(p),'-o',str(base/(name+'.log'))],stdout=subprocess.DEVNULL)
    log=(base/(name+'.log')).read_text()
    for key in ['output_common_mode_error_v','power_w','low_frequency_loop_gain_db','loop_ugb_hz','phase_margin_deg','rise_output_at_10ns','fall_output_at_10ns','high_static_output','low_static_output','fall_settling_time_s','rise_settling_time_s','output_noise_vrms']:
     m=re.search(r'\b'+key+r'\s*=\s*([-+\deE.]+)',log)
     if m:row[key]=float(m[1])
   out.append(row);print(row,flush=True)
   (base/'matrix.json').write_text(json.dumps(out,indent=2))
PY
python3 /app/experiments/matrix.py > /app/experiments/matrix_progress.log 2>&1

tail -12 /app/experiments/matrix_progress.log; ls -lt /app/experiments/*ff* | head; cat /app/experiments/matrix.py | tail -18; python3 - <<'PY'
