for p in Path('/proc').glob('[0-9]*/cmdline'):
 try:
  c=p.read_bytes().replace(b'\0',b' ')
  if c.startswith(b'python3 /app/experiments') or c.startswith(b'ngspice'):print(p,c)
 except:pass
